package com.mendes.scheduling_platform.tenant; import com.mendes.scheduling_platform.exception.*; import com.mendes.scheduling_platform.subscription.*; import com.mendes.scheduling_platform.user.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*;
@Service public class TenantService { private final TenantRepository tenants; private final UserRepository users; private final SubscriptionRepository subscriptions; private final PasswordEncoder encoder; public TenantService(TenantRepository t,UserRepository u,SubscriptionRepository s,PasswordEncoder e){tenants=t;users=u;subscriptions=s;encoder=e;} public record Registration(String name,String slug,String ownerName,String email,String password,String phone,String address){} @Transactional public Tenant register(Registration r){String slug=r.slug().trim().toLowerCase();if(tenants.existsBySlug(slug))throw new BusinessException("Slug já utilizado");Tenant t=new Tenant();t.setName(r.name());t.setSlug(slug);t.setPhone(r.phone());t.setAddress(r.address());t.setPlan("STARTER");t=tenants.save(t);User u=new User();u.setTenantId(t.getId());u.setName(r.ownerName());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));u.setRole(User.Role.OWNER);users.save(u);Subscription s=new Subscription();s.setTenantId(t.getId());s.setPlan("STARTER");s.setStatus(Subscription.Status.TRIAL);s.setStartDate(LocalDate.now());s.setEndDate(LocalDate.now().plusDays(14));subscriptions.save(s);return t;} }
